"""Compare the actual saved results of the two trained Wine classifiers."""

from pathlib import Path

import matplotlib.pyplot as plt
import pandas as pd
import seaborn as sns


# Load only the metrics generated by the model-evaluation scripts.
output_directory = Path("outputs")
random_forest_results = pd.read_csv(output_directory / "random_forest_results.csv")
neural_network_results = pd.read_csv(output_directory / "neural_network_results.csv")

# Combine the result rows into one concise comparison table.
metric_columns = ["Model", "Accuracy", "Precision", "Recall", "F1-score"]
comparison_table = pd.concat(
    [random_forest_results, neural_network_results], ignore_index=True
)[metric_columns]

print("MODEL COMPARISON")
print("=" * 50)
print(comparison_table.to_string(index=False))

# Save the table for the final project summary.
comparison_file = output_directory / "model_comparison.csv"
comparison_table.to_csv(comparison_file, index=False)

# Reshape the table so seaborn can group bars by performance metric.
chart_data = comparison_table.melt(
    id_vars="Model",
    value_vars=["Accuracy", "Precision", "Recall", "F1-score"],
    var_name="Metric",
    value_name="Score",
)

figures_directory = output_directory / "figures"
figures_directory.mkdir(parents=True, exist_ok=True)
sns.set_theme(style="whitegrid")
plt.figure(figsize=(11, 7))
sns.barplot(data=chart_data, x="Metric", y="Score", hue="Model")
plt.title("Model Performance Comparison")
plt.xlabel("Metric")
plt.ylabel("Score")
plt.ylim(0, 1.05)
plt.tight_layout()
comparison_plot_file = figures_directory / "10_model_performance_comparison.png"
plt.savefig(comparison_plot_file, dpi=300)
plt.close()

print(f"\nComparison table saved to: {comparison_file}")
print(f"Comparison figure saved to: {comparison_plot_file}")
